    LutInt = 0 	# Interpolation method
    L1 = 1 	# Lookup table elements...
    L2 = 1.5
    L3 = 2
    L4 = 2.5
    L5 = 3
    L6 = 3.5
    L7 = 4
    L8 = 4.5
    L9 = 5
 End LutMap
